(p/'main.js').write_text('''var base=new URL('.',location.href).href;var viz=new Spacekit.Simulation(document.getElementById('scene'),{basePath:base,jdPerSecond:.05,unitsPerAu:1,camera:{initialPosition:[0,-3.5,1.6]}});viz.createLight([-5,-5,4]);viz.createStars({minSize:.55});var radius=58232.503/149598000;var objects={earth:viz.createSphere('earth',{textureUrl:base+'earth.jpg',radius:1,atmosphere:{enable:true,color:0x4288d9,outerSizeRatio:.035},levelsOfDetail:[{radii:0,segments:48}]}),jupiter:viz.createSphere('jupiter',{textureUrl:base+'jupiter.jpg',radius:1,levelsOfDetail:[{radii:0,segments:48}]}),saturn:viz.createSphere('saturn',{textureUrl:base+'saturn.png',radius:radius,axialTilt:26.7,levelsOfDetail:[{radii:0,segments:48}]})};objects.saturn.addRings(74270.580913,140478.924731,base+'rings.png',96);var controls=viz.getViewer().get3jsCameraControls();controls.autoRotate=true;controls.autoRotateSpeed=.8;controls.enablePan=false;var names={earth:'地球 · 蓝色家园',jupiter:'木星 · 风暴巨人',saturn:'土星 · 冰尘之环'},current='earth';function select(id){current=id;Object.keys(objects).forEach(function(k){objects[k].get3jsObjects().forEach(function(o){o.visible=k===id})});viz.zoomToFit(objects[id],id==='saturn'?1.5:1.15).then(function(){controls.minDistance=id==='saturn'?radius*2.8:1.4;controls.maxDistance=id==='saturn'?radius*14:8;controls.update()});document.getElementById('title').textContent=names[id];document.querySelectorAll('[data-planet]').forEach(function(b){b.classList.toggle('active',b.dataset.planet===id)})}document.querySelectorAll('[data-planet]').forEach(function(b){b.onclick=function(){select(b.dataset.planet)}});document.getElementById('spin').onclick=function(){controls.autoRotate=!controls.autoRotate;this.textContent=controls.autoRotate?'暂停巡航':'自动巡航'};select('earth');window.addEventListener('pagehide',function(){viz.stop();viz.getRenderer().dispose()});''')
(p/'index.html').write_text(index('<div id="scene"></div><div class="head"><h1 id="title">正在加载天体…</h1><p>Spacekit · 拖动环绕 · 滚轮缩放</p></div><div class="controls"><button data-planet="earth" class="active">地球</button><button data-planet="jupiter">木星</button><button data-planet="saturn">土星</button><button id="spin">暂停巡航</button></div>','<script src="spacekit.js"></script><script src="main.js"></script>'))
